document.addEventListener('DOMContentLoaded',()=>{document.querySelector('#about').onclick=()=>{const body=document.querySelector('#detailBody');body.replaceChildren();const add=(tag,t)=>{const el=document.createElement(tag);el.textContent=t;body.append(el);return el};add('h2','一个三语 AI 阅读实验');add('p','本库收录《逻辑哲学论》99 条不同编号的完整命题。中文由本项目 AI 助手依据德语试译，并参考 Ogden 英译；未经专业审校，不替代正式译本，也不表示作者本人认可项目的分类和解读。');add('h3','文字与版权');add('p','德语：Ludwig Wittgenstein，1922 年德英对照版。英文：C. K. Ogden，协同 F. P. Ramsey，1922 年译本。电子底本为 Project Gutenberg #5740；该站标明此电子书在美国属于公有领域，这不是全球统一的版权结论，其他地区需依当地规定判断。');add('p','中文：AI 实验译文，不采用韩林合或其他既有中文出版译本。我们未取得、也不声称取得这些出版译本的授权。简短表述与通行译法可能重合。中文 AI 产物能否获得版权保护、权利归属及再利用条件，须依适用法律与具体创作过程判断；本项目不声称独占维特根斯坦的思想或原文。');add('p','made by kaemi 是项目制作署名，不是原作或 Ogden 英译的作者署名。本声明用于说明来源与创作方式，并不代替法律判断或第三方授权。');add('h3','图片与音乐');add('p','肖像：Moritz Nähr，1928/29，Wikimedia Commons 标记为公有领域。音乐：勃拉姆斯 Op.117 No.1，La Pianista 2012 年录音，CC BY-SA 3.0；录音使用许可独立于文字，详情见首页“音乐与来源”。');[['电子底本与版权标注 ↗','https://www.gutenberg.org/ebooks/5740'],['逐条来源、术语和处理说明 ↗','./TEXT_SOURCES.md']].forEach(([t,url])=>{const a=add('a',t);a.href=url;a.target='_blank';a.rel='noopener noreferrer'});document.querySelector('#detail').showModal()}});
